import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"03 · 调度与并发同步：CPU 分给谁，共享数据谁先动","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/os/03.md","filePath":"bagu/os/03.md"}'),l={name:"bagu/os/03.md"};function o(e,s,p,r,d,h){return t(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_03-·-调度与并发同步-cpu-分给谁-共享数据谁先动" tabindex="-1">03 · 调度与并发同步：CPU 分给谁，共享数据谁先动 <a class="header-anchor" href="#_03-·-调度与并发同步-cpu-分给谁-共享数据谁先动" aria-label="Permalink to &quot;03 · 调度与并发同步：CPU 分给谁，共享数据谁先动&quot;">​</a></h1><blockquote><p>这篇有两个主题，它们其实是同一件事的两面：<strong>调度</strong>决定&quot;谁用 CPU&quot;，<strong>同步</strong>决定&quot;谁用共享数据&quot;。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><ul><li><strong>调度</strong>：CPU 只有一个（或几个），程序有一堆，按什么规则排队。</li><li><strong>同步</strong>：多个执行流要改同一份数据，怎么保证不出错且不太慢。</li></ul><h2 id="生活类比-餐厅后厨" tabindex="-1">生活类比：餐厅后厨 <a class="header-anchor" href="#生活类比-餐厅后厨" aria-label="Permalink to &quot;生活类比：餐厅后厨&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>餐厅</th></tr></thead><tbody><tr><td>调度器</td><td>排号叫号的服务员</td></tr><tr><td>时间片</td><td>每桌限时 10 分钟，到点必须让位</td></tr><tr><td>优先级</td><td>有预约的客人可以插队</td></tr><tr><td>互斥锁</td><td>灶台只有一口锅，谁占了别人只能等</td></tr><tr><td>自旋锁</td><td>站着一直盯着锅，不坐下（不释放 CPU）</td></tr><tr><td>读写锁</td><td>菜谱可以多人同时看（读），但要改菜谱必须清场（写）</td></tr><tr><td>死锁</td><td>厨师 A 拿着刀等锅，厨师 B 拿着锅等刀</td></tr><tr><td>条件变量</td><td>等汤炖好，先睡一会，好了叫你</td></tr></tbody></table><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、调度算法-只要记住-为什么演进" tabindex="-1">一、调度算法（只要记住&quot;为什么演进&quot;） <a class="header-anchor" href="#一、调度算法-只要记住-为什么演进" aria-label="Permalink to &quot;一、调度算法（只要记住&quot;为什么演进&quot;）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FCFS（先来先服务）</span></span>
<span class="line"><span>  +- 问题：一个长任务堵在前面，后面全等 &gt;  convoy effect（护航效应）</span></span>
<span class="line"><span>      v 改进：谁短谁先</span></span>
<span class="line"><span>SJF（短作业优先）</span></span>
<span class="line"><span>  +- 问题：长任务可能永远排不上（饥饿）；而且&quot;运行时间&quot;根本预知不了</span></span>
<span class="line"><span>      v 改进：给个时间片，轮着来</span></span>
<span class="line"><span>RR（时间轮转）</span></span>
<span class="line"><span>  +- 问题：所有进程一视同仁，交互式任务和后台批处理没区别</span></span>
<span class="line"><span>      v 改进：分优先级 + 动态调整</span></span>
<span class="line"><span>多级反馈队列（MLFQ）</span></span>
<span class="line"><span>  +- 新进程进最高优先级队列，用完时间片就降级；</span></span>
<span class="line"><span>     高优先级队列时间片短，低优先级时间片长；</span></span>
<span class="line"><span>     定期把所有人提回最高优先级（防饥饿）</span></span></code></pre></div><p><strong>MLFQ 是实际系统的主流思路</strong>（Linux 的 CFS 是另一种：按&quot;已用 CPU 时间&quot;排序，用红黑树维护，谁用得少谁先上，追求公平而非优先级）。</p><p><strong>必考点：抢占 vs 非抢占</strong></p><ul><li>抢占式：时间片到、或有更高优先级任务到达，立即切换。现代系统都是抢占式。</li><li>非抢占式：进程自己让出才切换。实现简单，但一个死循环能卡死整个系统。</li></ul><h3 id="二、锁-三种粒度" tabindex="-1">二、锁：三种粒度 <a class="header-anchor" href="#二、锁-三种粒度" aria-label="Permalink to &quot;二、锁：三种粒度&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 互斥锁（Mutex）—— 抢不到就睡</span></span>
<span class="line"><span>   线程 A 拿锁 &gt; 线程 B 来抢 &gt; B 被挂起，进等待队列 &gt; A 释放 &gt; 唤醒 B</span></span>
<span class="line"><span>   优点：不浪费 CPU</span></span>
<span class="line"><span>   缺点：挂起/唤醒要走内核，开销约 1~2 微秒</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 自旋锁（Spinlock）—— 抢不到就转圈</span></span>
<span class="line"><span>   线程 B：while (锁没拿到) { }   &lt; 一直占着 CPU 空转</span></span>
<span class="line"><span>   优点：没有内核开销，锁持有时间极短时更快</span></span>
<span class="line"><span>   缺点：空转烧 CPU；单核上毫无意义（占着 CPU 别人没法释放锁）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 读写锁（RWLock）—— 读读并行，读写/写写互斥</span></span>
<span class="line"><span>   适合&quot;读多写少&quot;。但写操作可能被源源不断的读饿死（需公平策略）</span></span></code></pre></div><p><strong>怎么选</strong>：临界区极短（几十条指令）用自旋；可能阻塞（有 IO、可能等很久）用互斥。这也是为什么内核里大量用自旋锁（临界区都是纯内存操作），用户态程序几乎只用互斥锁。</p><h3 id="三、死锁-四个必要条件-四种处理策略" tabindex="-1">三、死锁：四个必要条件 + 四种处理策略 <a class="header-anchor" href="#三、死锁-四个必要条件-四种处理策略" aria-label="Permalink to &quot;三、死锁：四个必要条件 + 四种处理策略&quot;">​</a></h3><p><strong>四个条件（必须同时满足才会死锁）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 互斥      资源不能被共享，一次只能一个占</span></span>
<span class="line"><span>② 持有并等待 占着一个，同时还在等另一个</span></span>
<span class="line"><span>③ 不可剥夺   别人不能强行抢走我占的资源</span></span>
<span class="line"><span>④ 循环等待   存在一个环：A 等 B，B 等 A</span></span></code></pre></div><p><strong>破一个就能破死锁</strong>，这决定了四种策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>现实中的例子</th></tr></thead><tbody><tr><td><strong>预防</strong></td><td>破坏某个条件。最常用是破坏&quot;循环等待&quot;：<strong>所有资源按全局顺序申请</strong></td><td>数据库规定&quot;按主键顺序加锁&quot;</td></tr><tr><td><strong>避免</strong></td><td>分配前算一下&quot;给了会不会不安全&quot;（银行家算法）</td><td>实际很少用，要预知最大需求</td></tr><tr><td><strong>检测+恢复</strong></td><td>定期查资源分配图有没有环，有就回滚/杀进程</td><td>数据库的死锁检测（超时 + 等待图）</td></tr><tr><td><strong>鸵鸟策略</strong></td><td>假装看不见，死锁概率极低就不管</td><td>大多数 OS 的选择</td></tr></tbody></table><p><strong>为什么&quot;按顺序申请&quot;能破死锁</strong>：如果所有人都按 A&gt;B&gt;C 的顺序申请，就不可能出现&quot;A 拿 B 等 A&quot;这种环——因为要形成环，必须有人逆序申请。</p><h3 id="四、无锁-cas-与它的坑" tabindex="-1">四、无锁：CAS 与它的坑 <a class="header-anchor" href="#四、无锁-cas-与它的坑" aria-label="Permalink to &quot;四、无锁：CAS 与它的坑&quot;">​</a></h3><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 伪代码：比较并交换（CPU 提供的一条原子指令）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CAS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int*</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> addr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> expected</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> new_val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">addr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> expected) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">addr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> new_val; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>为什么无锁快</strong>：没有&quot;挂起/唤醒&quot;的内核开销，失败就重试，纯用户态完成。适合<strong>冲突少</strong>的场景。</p><p><strong>三个坑</strong>：</p><ol><li><strong>ABA 问题</strong>：值从 A 改成 B 又改回 A，CAS 以为&quot;没变过&quot;就成功了，但实际上中间状态被改过。解法：加版本号（<code>AtomicStampedReference</code>）。</li><li><strong>自旋开销</strong>：冲突激烈时，大量线程空转重试，CPU 全烧在失败上。</li><li><strong>只能保护单个变量</strong>：多个变量要一起改，CAS 做不到（需要锁或事务内存）。</li></ol><h3 id="五、条件变量-解决-等-的问题" tabindex="-1">五、条件变量：解决&quot;等&quot;的问题 <a class="header-anchor" href="#五、条件变量-解决-等-的问题" aria-label="Permalink to &quot;五、条件变量：解决&quot;等&quot;的问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生产者：</span></span>
<span class="line"><span>  lock(mutex)</span></span>
<span class="line"><span>  while (队列满了) wait(cond_not_full, mutex)   &lt; wait 会原子地释放锁并睡眠</span></span>
<span class="line"><span>  放入元素</span></span>
<span class="line"><span>  signal(cond_not_empty)                        &lt; 唤醒一个消费者</span></span>
<span class="line"><span>  unlock(mutex)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>消费者：</span></span>
<span class="line"><span>  lock(mutex)</span></span>
<span class="line"><span>  while (队列空了) wait(cond_not_empty, mutex)</span></span>
<span class="line"><span>  取出元素</span></span>
<span class="line"><span>  signal(cond_not_full)</span></span>
<span class="line"><span>  unlock(mutex)</span></span></code></pre></div><p><strong>两个必考细节</strong>：</p><ol><li><strong>为什么用 <code>while</code> 不用 <code>if</code>？</strong> 因为被唤醒后，条件可能又被别人改回去了（虚假唤醒 + 竞争）。必须重新检查。</li><li><strong><code>wait</code> 为什么要&quot;原子地释放锁&quot;？</strong> 如果先释放锁再睡，中间可能错过 signal（生产者在你睡之前就通知了），导致永久等待。</li></ol><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果不用时间片-会怎样" tabindex="-1">反事实 1：如果不用时间片，会怎样 <a class="header-anchor" href="#反事实-1-如果不用时间片-会怎样" aria-label="Permalink to &quot;反事实 1：如果不用时间片，会怎样&quot;">​</a></h3><p>一个死循环程序会永久占住 CPU，整个系统假死。这就是早期非抢占式系统（如 Windows 3.1）频繁蓝屏/卡死的原因。</p><h3 id="反事实-2-如果锁不存在-会怎样" tabindex="-1">反事实 2：如果锁不存在，会怎样 <a class="header-anchor" href="#反事实-2-如果锁不存在-会怎样" aria-label="Permalink to &quot;反事实 2：如果锁不存在，会怎样&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>i++ 在汇编层是三步：</span></span>
<span class="line"><span>  ① 从内存读 i 到寄存器</span></span>
<span class="line"><span>  ② 寄存器加 1</span></span>
<span class="line"><span>  ③ 写回内存</span></span></code></pre></div><p>两个线程同时执行，可能都读到 <code>i=5</code>，都加 1 写回 6。<strong>两次自增，结果只加了 1</strong>。这就是&quot;数据竞争&quot;，它的可怕之处是<strong>偶发</strong>——测试环境跑一万次都对，线上高并发时出错。</p><h3 id="反事实-3-如果只有锁、没有-cas-会怎样" tabindex="-1">反事实 3：如果只有锁、没有 CAS，会怎样 <a class="header-anchor" href="#反事实-3-如果只有锁、没有-cas-会怎样" aria-label="Permalink to &quot;反事实 3：如果只有锁、没有 CAS，会怎样&quot;">​</a></h3><p>所有并发控制都要走内核挂起/唤醒。高并发下（比如 100 个线程抢一个计数器），大部分时间花在&quot;睡下、被叫醒&quot;上，吞吐量极低。CAS 让&quot;抢不到&quot;变成&quot;重试一下&quot;，在低冲突时几乎零成本。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：死锁的四个必要条件？怎么预防？</strong></p><blockquote><p>四个条件背完，重点在**&quot;破坏哪一个&quot;**：最实用的是破坏循环等待——<strong>所有线程按同一全局顺序申请锁</strong>。其次是破坏持有并等待——<strong>一次性申请所有资源</strong>（代价是利用率低）。</p></blockquote><p><strong>Q：自旋锁和互斥锁怎么选？</strong></p><blockquote><p>看<strong>临界区长度</strong>和<strong>是否可能阻塞</strong>。 临界区只有几条指令、且确定不会阻塞 &gt; 自旋（省掉内核切换）。 可能等 IO、或者临界区较长 &gt; 互斥（自旋会白烧 CPU）。 单核 CPU 上不要用自旋锁（占着唯一的核，持有者永远没法运行来释放锁）。</p></blockquote><p><strong>Q：CAS 有什么问题？</strong></p><blockquote><p>三个：ABA、自旋开销、只能保护单个变量。ABA 用版本号解决。</p></blockquote><p><strong>Q：为什么 wait 必须放在 while 里？</strong></p><blockquote><p>两个原因：① <strong>虚假唤醒</strong>（OS 可能无故唤醒）；② <strong>唤醒后条件可能已不成立</strong>（被别的线程抢走了）。用 <code>if</code> 只检查一次，会带着错误的前提继续执行。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>死锁怎么产生？</span></span>
<span class="line"><span>  &gt; 四个必要条件是什么？</span></span>
<span class="line"><span>    &gt; 破坏哪个最实用？（循环等待 &gt; 全局顺序）</span></span>
<span class="line"><span>      &gt; 数据库怎么处理死锁？（等待图 + 回滚代价最小的那个事务）</span></span>
<span class="line"><span>        &gt; 那不用锁行不行？（CAS 无锁）</span></span>
<span class="line"><span>          &gt; CAS 有什么坑？（ABA / 自旋 / 单变量）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/01">进程与线程：谁在跑，跑的时候带着什么</a>：线程是调度的基本单位，共享堆是加锁的原因</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/02">虚拟内存：让每个程序都以为自己独占一台机器</a>：抖动的解法之一是&quot;降低多道程度&quot;，属于调度范畴</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：阻塞 IO 让进程进入阻塞态，触发调度；IO 多路复用是&quot;用一次等待处理多个 fd&quot;</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/03">隔离级别与 MVCC</a>：MVCC 就是为了<strong>减少加锁</strong>，用&quot;读旧版本&quot;替代&quot;读时加锁&quot;</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/04">锁与死锁</a>：数据库死锁与 OS 死锁同源，但多了&quot;间隙锁&quot;这种粒度</li><li><strong>&gt; 影响</strong> 语言层：Java 的 <code>synchronized</code>（管程）、<code>AQS</code>（CLH 队列 + CAS）、Go 的 <code>channel</code>（CSP）都是这套理论的不同包装</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么&quot;按全局顺序申请锁&quot;能避免死锁？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为死锁的第四条件是&quot;循环等待&quot;，而循环等待要求存在一个环：A 等 B 的资源，B 等 A 的资源。</p><p>如果所有人按 A&gt;B&gt;C 的固定顺序申请，那么&quot;持有 B 等 A&quot;这种情况<strong>不可能发生</strong>（因为拿 B 之前必须先拿到 A）。没有逆序申请，就构不成环。</p><p>代价：可能降低并发度（本来可以并行申请的锁，现在必须串行），也可能需要开发者知道全局顺序（跨模块时很难保证）。</p></details><p><strong>Q2：单核 CPU 上用自旋锁为什么没意义？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为只有一个核。线程 B 自旋时，占着唯一的 CPU 空转，持有锁的线程 A <strong>根本没有机会运行来释放锁</strong>。</p><p>结果就是 B 一直转到时间片用完，被强制换下，A 才有机会跑。自旋期间 CPU 100% 被浪费。</p><p>所以单核上应该用互斥锁（让 B 睡下，把 CPU 让给 A）。<strong>自旋锁的前提是&quot;持有者能在另一个核上并行运行&quot;</strong>。</p></details><p><strong>Q3：乐观锁和悲观锁，本质区别是什么？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>区别在<strong>冲突概率的假设</strong>，进而决定了&quot;先加锁还是先干活&quot;：</p><ul><li><strong>悲观锁</strong>：假设一定会冲突 &gt; 先加锁再操作 &gt; 冲突时等待。适合<strong>写多、冲突多</strong>。</li><li><strong>乐观锁</strong>：假设大概率不冲突 &gt; 先操作，提交时用 CAS/版本号检查有没有被别人改过 &gt; 冲突就重试或报错。适合<strong>读多、冲突少</strong>。</li></ul><p>注意：<strong>乐观锁不是一种&quot;锁&quot;</strong>，它没有任何加锁动作，只是一种&quot;提交时校验&quot;的策略。数据库的 <code>version</code> 字段、Java 的 <code>AtomicInteger</code> 都属于这一类。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;灶台只有一口锅&quot;会让人以为锁的粒度是固定的</strong>。实际上锁可以细到&quot;一个变量&quot;（原子变量）、粗到&quot;整张表&quot;（表锁）。粒度越细并发越高，但管理成本也越高。</li><li><strong>自旋锁不是&quot;更快的锁&quot;</strong>。它只是在特定场景（临界区极短 + 多核）更快，其他场景更慢。</li><li><strong>死锁 ≠ 饥饿</strong>。死锁是&quot;互相等，永远解不开&quot;；饥饿是&quot;一直排不上队，但系统还在动&quot;。活锁又是另一种：大家都在动，但一直互相谦让，谁也没进展。</li><li><strong><code>volatile</code> 不保证原子性</strong>。它只保证可见性和禁止重排序，<code>i++</code> 依然不安全。这是最经典的面试陷阱。</li><li><strong>&quot;抢占式调度&quot;不代表&quot;随时能抢&quot;</strong>。内核态临界区里通常关抢占，否则会破坏内核数据结构。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出 FCFS &gt; SJF &gt; RR &gt; MLFQ 每一代解决了上一代的什么问题</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能默写死锁四个必要条件，并对每个条件说出一种破坏手段</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说清自旋锁和互斥锁的选择依据（临界区长度 + 是否多核 + 是否可能阻塞）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释 CAS 的三个坑，并说出 ABA 的解法</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释 <code>wait</code> 为什么必须在 <code>while</code> 里、为什么必须原子地释放锁</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能用&quot;i++ 三步&quot;讲清数据竞争为什么是偶发的</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,62)])])}const u=a(l,[["render",o]]);export{g as __pageData,u as default};
